 branches=[['拿捏分寸','moderate, moderation, moderator, modest, modesty, modicum'],['样式与单元','model, modeling, module, modular, modularity'],['方式与峰','mode, modal, modality, multimodal, bimodal, unimodal'],['调节声音和信号','modulate, modulation, demodulate, intermodulation'],['当下与现代','modern, modernize, modernity, modernism, postmodern'],['合适、便利、可交易','accommodate, accommodation, commodity, commodification, commode'],['专业的小尺度','modulus, modulo, unimodular, bimodule, modiolus']],
